xpath.script:
(function(){
    var v = '; ' + document.cookie;
    var p = v.split('; googtrans=');
    if (p.length !== 2) return;
    var val = p.pop().split(';').shift();
    if (!val) return;
    if (val === '/en/en') return;
    if (val === '/en/') return;
    if (val === 'null') return;

    /* Cookie is active — hide body immediately */
    document.documentElement.classList.add('ot-pre-translate');

    /* Create hidden mount for Google Translate widget */
    var el = document.createElement('div');
    el.id = 'google_translate_element_hidden';
    el.style.display = 'none';
    document.documentElement.appendChild(el);

    /* Define the init callback */
    window.googleTranslateElementInit = function() {
        if (window.google) {
            new google.translate.TranslateElement({
                pageLanguage: 'en',
                layout: google.translate.TranslateElement.InlineLayout.SIMPLE,
                autoDisplay: false
            }, 'google_translate_element_hidden');
        }
    };

    /* Start downloading Google Translate script RIGHT NOW — during head parsing */
    var s = document.createElement('script');
    s.src = 'https://translate.google.com/translate_a/element.js?cb=googleTranslateElementInit';
    document.documentElement.appendChild(s);
})();
